INSERT INTO "producer" ("id", "user_id", "nip", "name", "country_code", "rating", "review_count", "technology", "verification_status", "created_at", "updated_at", "deleted_at", "production_scale", "inquiry_response_time_label", "showroom_visit_available", "showroom_visit_note", "description", "communication_locale", "is_platform_brand") VALUES ('e0030000-0000-4000-8000-000000000111', 'catalog-import:kunert', '4990661888', 'Kunert Mobile Homes', 'PL', NULL, 0, 'modulowa-stal-lekka', 'not_submitted', '2026-11-20T16:32:32.503Z'::timestamptz, '2026-11-20T17:38:42.143Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Producent domów mobilnych z Koszalina, działający od 1997 roku. Projektuje i buduje domy mobilne na ramie stalowej, od kompaktowych modeli 24 m² po rodzinne domy z trzema sypialniami i dwiema łazienkami, do użytku całorocznego lub sezonowego. Dostarcza domy w Polsce i do innych krajów Europy, m.in. do Niemiec i Holandii, także dla ośrodków wypoczynkowych i parków domków.', 'pl', false) ON CONFLICT DO NOTHING;
