INSERT INTO "producer_member" ("id", "producer_id", "user_id", "added_by", "created_at") VALUES ('a37e0361-926b-49a4-9906-f5873c067f83', 'e0030000-0000-4000-8000-000000000111', 'catalog-import:kunert', NULL, '2026-11-20T16:32:32.503Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('4619ef8b-5a84-4caa-9c94-b2bd5b8bd941', 'e0030000-0000-4000-8000-000000000111', 'nl', 'Producent van mobiele huizen uit Koszalin, Polen, actief sinds 1997. Het bedrijf ontwerpt en bouwt mobiele huizen op een stalen frame, van compacte modellen van 24 m² tot gezinswoningen met drie slaapkamers en twee badkamers, voor gebruik het hele jaar of per seizoen. Er wordt geleverd in Polen en naar andere Europese landen, waaronder Duitsland en Nederland, ook voor vakantieparken.', NULL, NULL, '2026-11-20T16:32:32.503Z'::timestamptz, '2026-11-20T17:38:42.143Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('09e239d8-2cd1-45cd-90ad-afbf1a206697', 'e0030000-0000-4000-8000-000000000111', 'en', 'Mobile home producer from Koszalin, Poland, in business since 1997. It designs and builds mobile homes on a steel frame, from compact 24 m² models to family homes with three bedrooms and two bathrooms, for year-round or seasonal use. Homes are delivered within Poland and to other European countries, including Germany and the Netherlands, also for holiday resorts and holiday parks.', NULL, NULL, '2026-11-20T16:32:32.503Z'::timestamptz, '2026-11-20T17:38:42.143Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('f3038e97-49a3-4d5d-b0bc-52bfba95f008', 'e0030000-0000-4000-8000-000000000111', 'de', 'Hersteller mobiler Häuser aus Koszalin, Polen, seit 1997 tätig. Das Unternehmen plant und baut mobile Häuser auf einem Stahlrahmen, von kompakten 24 m² Modellen bis zu Familienhäusern mit drei Schlafzimmern und zwei Bädern, für ganzjährige oder saisonale Nutzung. Geliefert wird in Polen und in andere europäische Länder, u. a. nach Deutschland und in die Niederlande, auch für Ferienanlagen und Ferienparks.', NULL, NULL, '2026-11-20T16:32:32.503Z'::timestamptz, '2026-11-20T17:38:42.143Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('a535b585-eea2-44d7-95d9-fcab9a034b49', 'Dom mobilny jest dostarczany w całości z fabryki. Wymagania lokalne (zgłoszenie, podłączenia, posadowienie) zależą od kraju i działki.', 'nl', 'Het mobiele huis wordt compleet vanuit de fabriek geleverd. Lokale eisen (melding, aansluitingen, fundering) hangen af van het land en het perceel.', '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:23:06.409Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('54404f3c-d3c9-4a41-a8fe-9267c194b532', 'Dom mobilny jest dostarczany w całości z fabryki. Wymagania lokalne (zgłoszenie, podłączenia, posadowienie) zależą od kraju i działki.', 'de', 'Das mobile Haus wird komplett ab Werk geliefert. Lokale Anforderungen (Anzeige, Anschlüsse, Aufstellung) hängen vom Land und vom Grundstück ab.', '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:23:06.409Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('c05dbc65-c681-4535-a5e0-c74ace15bc86', 'Dom mobilny jest dostarczany w całości z fabryki. Wymagania lokalne (zgłoszenie, podłączenia, posadowienie) zależą od kraju i działki.', 'en', 'The mobile home is delivered complete from the factory. Local requirements (notification, connections, foundation) depend on the country and the plot.', '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:23:06.409Z'::timestamptz) ON CONFLICT DO NOTHING;
